require 'grpc'
require 'logger'
require 'concurrent'

module AuditService
  class AuditLogger
    def initialize(log_path)
      @logger = Logger.new(log_path)
      @buffer = Concurrent::Array.new
      @flush_interval = 5
      @running = true
      @flush_thread = start_flush_thread
    end

    def log_event(event)
      @buffer << event.freeze
    end

    def shutdown
      @running = false
      @flush_thread.join(10)
      flush_buffer
      @logger.close
    end

    private

    def start_flush_thread
      Thread.new do
        while @running
          sleep(@flush_interval)
          flush_buffer
        end
      end
    end

    def flush_buffer
      events = @buffer.slice!(0, @buffer.length)
      events.each { |e| @logger.info(e.to_s) }
    end
  end

  class CallbackRegistry
    def initialize
      @callbacks = Concurrent::Hash.new
      @mutex = Mutex.new
    end

    def register(request_id, callback_context)
      @mutex.synchronize do
        @callbacks[request_id] = callback_context
      end
    end

    def resolve(request_id)
      @mutex.synchronize do
        @callbacks.delete(request_id)
      end
    end

    def pending_count
      @callbacks.size
    end
  end

  class RequestContext
    attr_reader :request_id, :user_id, :timestamp, :metadata

    def initialize(request_id, user_id, metadata = {})
      @request_id = request_id
      @user_id = user_id
      @timestamp = Time.now
      @metadata = metadata.freeze
    end

    def to_audit_event
      {
        request_id: @request_id,
        user_id: @user_id,
        timestamp: @timestamp.iso8601,
        metadata: @metadata
      }.freeze
    end
  end

  class AsyncProcessor
    def initialize(audit_logger, registry)
      @audit_logger = audit_logger
      @registry = registry
      @pool = Concurrent::ThreadPoolExecutor.new(
        min_threads: 2,
        max_threads: 8,
        max_queue: 100
      )
    end

    def process_async(context, &completion_handler)
      ctx_ref = context
      @registry.register(context.request_id, ctx_ref)

      @pool.post do
        begin
          result = perform_work(ctx_ref)
          finalize_request(ctx_ref, result, &completion_handler)
        rescue => e
          handle_error(ctx_ref, e, &completion_handler)
        end
      end
    end

    def cancel_request(request_id)
      resolved = @registry.resolve(request_id)
      if resolved
        @audit_logger.log_event({
          type: 'cancellation',
          request_id: request_id,
          timestamp: Time.now.iso8601
        })
      end
    end

    private

    def perform_work(context)
      sleep(rand(0.1..0.5))
      { status: :success, data: "processed_#{context.request_id}" }
    end

    def finalize_request(context, result, &completion_handler)
      audit_event = context.to_audit_event.merge(result: result[:status])
      @audit_logger.log_event(audit_event)
      @registry.resolve(context.request_id)
      completion_handler.call(context.to_audit_event, result) if completion_handler
    end

    def handle_error(context, error, &completion_handler)
      audit_event = context.to_audit_event.merge(
        result: :error,
        error_message: error.message
      )
      @audit_logger.log_event(audit_event)
      @registry.resolve(context.request_id)
      completion_handler.call(context.to_audit_event, { status: :error, error: error.message }) if completion_handler
    end
  end

  class GrpcServiceHandler
    def initialize
      @audit_logger = AuditLogger.new('/var/log/audit/grpc_service.log')
      @registry = CallbackRegistry.new
      @processor = AsyncProcessor.new(@audit_logger, @registry)
      @response_cache = Concurrent::Hash.new
    end

    def handle_request(request)
      context = RequestContext.new(
        request[:id],
        request[:user_id],
        request[:metadata] || {}
      )

      @processor.process_async(context) do |audit_snapshot, result|
        cache_response(audit_snapshot, result)
      end

      { accepted: true, request_id: request[:id] }
    end

    def handle_cancel(request_id)
      @processor.cancel_request(request_id)
      cached = @response_cache.delete(request_id)
      { cancelled: true, had_response: !cached.nil? }
    end

    def get_cached_response(request_id)
      entry = @response_cache[request_id]
      return nil unless entry
      {
        request_id: entry[:audit_snapshot][:request_id],
        user_id: entry[:audit_snapshot][:user_id],
        audit_trail: entry[:audit_snapshot],
        result: entry[:result]
      }
    end

    def shutdown
      @audit_logger.shutdown
    end

    private

    def cache_response(audit_snapshot, result)
      @response_cache[audit_snapshot[:request_id]] = {
        audit_snapshot: audit_snapshot,
        result: result,
        cached_at: Time.now
      }
    end
  end
end
